import{_ as a,o as s,c as d,a2 as i}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"并发与限流","description":"先看清并发问题的本质是共享状态被多路访问，再决定用锁、无锁结构还是限流来兜住它。","frontmatter":{"title":"并发与限流","description":"先看清并发问题的本质是共享状态被多路访问，再决定用锁、无锁结构还是限流来兜住它。"},"headers":[],"relativePath":"backend/concurrency.md","filePath":"backend/concurrency.md","lastUpdated":1786271684000}'),n={name:"backend/concurrency.md"};function e(l,t,p,h,r,o){return s(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="并发与限流" tabindex="-1">并发与限流 <a class="header-anchor" href="#并发与限流" aria-label="Permalink to &quot;并发与限流&quot;">​</a></h1><p>并发的本质不是&quot;多个线程同时跑&quot;，而是<strong>多个访问者同时读写同一份可变状态</strong>。没有共享状态就没有竞态，没有外部依赖的突发流量就需要限流。先把问题归类，再选手段，否则容易要么滥用锁把系统拖慢，要么堆限流策略却挡不住真正的故障。</p><h2 id="先分清并发问题的类型" tabindex="-1">先分清并发问题的类型 <a class="header-anchor" href="#先分清并发问题的类型" aria-label="Permalink to &quot;先分清并发问题的类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>典型现象</th><th>解决方向</th></tr></thead><tbody><tr><td>数据竞态</td><td>两个请求同时改库存，扣成负数</td><td>互斥 / 原子操作 / 数据库约束</td></tr><tr><td>状态不一致</td><td>读到写了一半的中间状态</td><td>隔离级别 / 事务 / 内存可见性</td></tr><tr><td>资源争抢</td><td>连接池打满、数据库被压垮</td><td>限流 / 排队 / 熔断</td></tr><tr><td>顺序依赖</td><td>任务 B 必须在 A 完成后执行</td><td>队列 / 显式编排</td></tr></tbody></table><p>判断不清时先问：<strong>这是&quot;算错了&quot;还是&quot;扛不住&quot;</strong>。算错了是正确性问题，靠锁和事务；扛不住是容量问题，靠限流和降级。两者混着治，往往两边都不见效。</p><h2 id="竞态条件-错误的根源" tabindex="-1">竞态条件：错误的根源 <a class="header-anchor" href="#竞态条件-错误的根源" aria-label="Permalink to &quot;竞态条件：错误的根源&quot;">​</a></h2><p>竞态发生的条件是&quot;读-改-写&quot;不是原子的：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>时刻1  请求A 读到库存 = 1</span></span>
<span class="line"><span>时刻2  请求B 读到库存 = 1</span></span>
<span class="line"><span>时刻3  请求A 写入库存 = 0，下单成功</span></span>
<span class="line"><span>时刻4  请求B 写入库存 = 0，下单成功   ← 超卖了</span></span></code></pre></div><p>只要&quot;判断&quot;和&quot;修改&quot;中间留了空隙，并发就可能钻进来。能消除空隙就不需要锁，消除不了再上锁。</p><h2 id="锁与替代方案" tabindex="-1">锁与替代方案 <a class="header-anchor" href="#锁与替代方案" aria-label="Permalink to &quot;锁与替代方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>适用场景</th><th>代价</th></tr></thead><tbody><tr><td>互斥锁</td><td>临界区明确、持锁时间短</td><td>阻塞、可能死锁</td></tr><tr><td>CAS / 原子操作</td><td>单变量更新、冲突少</td><td>冲突多时反复重试</td></tr><tr><td>乐观锁（版本号）</td><td>读多写少、可重试</td><td>冲突时需客户端重做</td></tr><tr><td>单线程串行（队列/Actor）</td><td>强依赖顺序、状态集中</td><td>吞吐受单点限制</td></tr><tr><td>数据库行锁 / <code>SELECT FOR UPDATE</code></td><td>跨进程的一致性</td><td>锁等待、死锁风险</td></tr></tbody></table><p>能用 CAS 和乐观锁就别用悲观锁。乐观锁的典型写法是带版本号更新：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 失败说明期间有人改过，由应用层重试</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> account </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> balance </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 7</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>这条 SQL 把&quot;读-改-写&quot;压进一条语句，空隙消失了，也就不需要应用层加锁。</p><h2 id="数据库行锁与隔离级别" tabindex="-1">数据库行锁与隔离级别 <a class="header-anchor" href="#数据库行锁与隔离级别" aria-label="Permalink to &quot;数据库行锁与隔离级别&quot;">​</a></h2><p>并发一致性最终往往落到数据库。隔离级别决定了&quot;并发执行时能看到什么&quot;：</p><table tabindex="0"><thead><tr><th>隔离级别</th><th>能防止</th><th>仍可能出现</th></tr></thead><tbody><tr><td>读未提交</td><td>—</td><td>脏读</td></tr><tr><td>读已提交（RC）</td><td>脏读</td><td>不可重复读、幻读</td></tr><tr><td>可重复读（RR）</td><td>不可重复读</td><td>部分数据库仍有幻读</td></tr><tr><td>串行化（Serializable）</td><td>几乎所有异常</td><td>吞吐大幅下降</td></tr></tbody></table><blockquote><p>隔离级别越高，正确性越稳，但并发吞吐越低。不要无脑拉到最高。</p></blockquote><p>对&quot;同一行不能被两个事务同时改&quot;的需求，用 <code>SELECT ... FOR UPDATE</code> 加行锁即可，不必把整个库的隔离级别调到串行化。业务里真正需要强隔离的场景（转账、对账）远比想象中少。</p><h2 id="限流-保护下游而不是惩罚用户" tabindex="-1">限流：保护下游而不是惩罚用户 <a class="header-anchor" href="#限流-保护下游而不是惩罚用户" aria-label="Permalink to &quot;限流：保护下游而不是惩罚用户&quot;">​</a></h2><p>限流解决的是容量问题，目标不是拒绝请求，而是<strong>让系统在过载时还能活着服务</strong>。三种常见算法各有定位：</p><table tabindex="0"><thead><tr><th>算法</th><th>特点</th><th>适合</th></tr></thead><tbody><tr><td>固定窗口</td><td>实现简单</td><td>粗粒度统计</td></tr><tr><td>滑动窗口</td><td>平滑、无边界突刺</td><td>API 配额、按用户限速</td></tr><tr><td>令牌桶</td><td>允许短时突发</td><td>入口网关、有波动的流量</td></tr><tr><td>漏桶</td><td>强制匀速出队</td><td>保护下游、平滑调用外部 API</td></tr></tbody></table><p>令牌桶和漏桶的区别要记住：<strong>令牌桶允许攒够令牌后短暂突发，漏桶强制匀速</strong>。保护数据库这种怕突刺的下游，漏桶更稳；面向用户 API 配额，令牌桶更友好。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>按谁限流：</span></span>
<span class="line"><span>  全局限流   → 防止整体过载</span></span>
<span class="line"><span>  按用户     → 防止单人打满</span></span>
<span class="line"><span>  按接口     → 防止昂贵接口被滥用</span></span>
<span class="line"><span>  按下游配额 → 防止打爆依赖的外部服务</span></span></code></pre></div><p>限流维度选错，等于没限。最容易漏的是&quot;按下游配额&quot;——你调用的第三方只给你 100 QPS，你却在入口按全局 1000 QPS 限流，结果自己没超限却把对方打挂。</p><h2 id="熔断与降级" tabindex="-1">熔断与降级 <a class="header-anchor" href="#熔断与降级" aria-label="Permalink to &quot;熔断与降级&quot;">​</a></h2><p>限流是&quot;我还能服务多少&quot;，熔断是&quot;我是否该停止尝试&quot;。当下游持续失败时，继续重试只会把双方都拖死：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>熔断器三态：</span></span>
<span class="line"><span>  Closed   正常调用，统计失败率</span></span>
<span class="line"><span>  Open     失败率超阈值，直接拒绝/走降级，不再请求下游</span></span>
<span class="line"><span>  Half-Open  探测性放行少量请求，成功则恢复</span></span></code></pre></div><p>熔断的判断维度通常是&quot;失败率 + 时间窗口&quot;，触发后必须配一个降级方案：返回缓存、返回默认值、返回部分结果。<strong>没有降级的熔断只是把错误换了个形态</strong>，用户体验并没有变好。</p><h2 id="何时串行-何时并行" tabindex="-1">何时串行，何时并行 <a class="header-anchor" href="#何时串行-何时并行" aria-label="Permalink to &quot;何时串行，何时并行&quot;">​</a></h2><p>这是一个经常被忽略的决策：</p><table tabindex="0"><thead><tr><th>场景</th><th>选择</th><th>原因</th></tr></thead><tbody><tr><td>多个独立、无依赖的任务</td><td>并行</td><td>缩短总耗时</td></tr><tr><td>依赖前一步结果的链路</td><td>串行</td><td>必须等</td></tr><tr><td>强一致写入（扣款、对账）</td><td>串行化关键路径</td><td>正确性优先</td></tr><tr><td>大量同类请求汇总</td><td>批处理 / 队列</td><td>平滑压力</td></tr></tbody></table><p>把本可并行的请求强行串行是性能浪费，把本该串行的写入强行并发是 bug 温床。判断依据始终是：<strong>它们之间有没有共享状态或顺序依赖</strong>。</p><h2 id="务实的检查清单" tabindex="-1">务实的检查清单 <a class="header-anchor" href="#务实的检查清单" aria-label="Permalink to &quot;务实的检查清单&quot;">​</a></h2><ul><li>先确认问题是正确性（竞态）还是容量（过载），对症下药。</li><li>能用单条带条件的 SQL 解决，就别在应用层加锁。</li><li>乐观锁优先于悲观锁，重试逻辑要明确写到客户端。</li><li>限流维度要覆盖&quot;全局 / 用户 / 接口 / 下游配额&quot;四层，尤其别漏下游。</li><li>熔断必须配降级方案，否则只是换个错误形态。</li><li>串行还是并行，看有没有共享状态或顺序依赖，而不是看&quot;感觉哪个快&quot;。</li></ul>`,35)])])}const u=a(n,[["render",e]]);export{k as __pageData,u as default};
